        --android-surface: #1e1e1e;
        --text-primary: #ffffff;
        --text-secondary: #9aa0a6;
        --system-bar-bg: #181818;
        --toast-bg: #323232;
        }

        * {
        box-sizing: border-box;
        margin: 0;
        padding: 0;
        }

        * {
        -webkit-tap-highlight-color: var(--highlight-color);
        user-select: none;
        -webkit-user-select: none;
        -ms-user-select: none;
        }

/* ==================== GENERAL ==================== */
