-size:.9rem;font-weight:600;border-radius:20px;white-space:nowrap;transition:background-color .2s,color .2s,border-color .2s}.season-tab.active{background-color:#fff;color:#121212;border-color:#fff}.episodes-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(70px,1fr));gap:12px;margin-top:8px}.episode-card{aspect-ratio:1/1;border:1px solid rgba(255,255,255,.08);border-radius:8px;display:flex;flex-direction:column;align-items:center;justify-content:center;transition:transform .15s,background-color .15s,border-color .15s}.episode-card:hover{background-color:rgba(255,255,255,.08);border-color:rgba(255,255,255,.2);transform:scale(1.05)}.episode-card:active{transform:scale(.95)}.episode-number{font-size:1.4rem;font-weight:700;color:#fff}.episode-tag{font-size:.65rem;letter-spacing:.5px;color:var(--text-secondary);margin-top:2px}.modal-overlay{position:fixed;inset:0;background-color:rgba(0,0,0,.75);z-index:1000;display:flex;justify-content:center;align-items:flex-end;visibility:hidden;opacity:0;transition:visibility .28s,opacity .28s}.bottom-sheet-modal{width:100%;max-width:540px;background-color:#1c1c1e;border-top-left-radius:20px;border-top-right-radius:20px;padding:24px 24px 40px;box-shadow:0 -8px 30px rgba(0,0,0,.5);transform:translateY(100%);transition:transform .28s cubic-bezier(.22, 1, .36, 1);max-height:85vh;overflow-y:auto}.modal-overlay.active .bottom-sheet-modal{transform:translateY(0)}.modal-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px;border-bottom:1px solid rgba(255,255,255,.08);padding-bottom:12px}.modal-title{font-size:1.15rem;font-weight:500;color:#fff}.close-modal-btn{background:0 0;border:none;color:var(--text-secondary);font-size:1.5rem;cursor:pointer;line-height:1;padding:4px}.servers-list{display:flex;flex-direction:column;gap:12px;margin-bottom:24px}.server-item{display:flex;justify-content:space-between;align-items:center;background-color:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.06);border-radius:12px;padding:14px 18px}.server-meta{display:flex;flex-direction:column;gap:4px}.server-name{font-size:.95rem;font-weight:600;color:#fff}.server-lang{font-size:.78rem;color:var(--text-secondary);background-color:rgba(255,255,255,.06);padding:2px 6px;border-radius:4px;width:fit-content;letter-spacing:.3px}.server-play-btn{border:none;padding:8px 16px;border-radius:8px;font-weight:600;font-size:.85rem;cursor:pointer;display:inline-flex;align-items:center;gap:6px;transition:background-color .2s,transform .1s}.server-play-btn:hover{background-color:#fff!important;color:#121212!important}.video-player-overlay{position:fixed;inset:0;background-color:#000;z-index:2000;display:none;flex-direction:column}.video-player-overlay.active{display:flex}.video-header{height:56px;background-color:rgba(0,0,0,.8);display:flex;align-items:center;padding:0 16px;gap:16px;position:absolute;top:0;left:0;right:0;z-index:2010}.video-frame-container{flex-grow:1;width:100%;height:100%;display:flex;align-items:center;justify-content:center;background-color:#000}.video-frame{width:100%;height:100%;border:none}.android-toast{position:fixed;bottom:60px;left:50%;transform:translateX(-50%) translateY(20px);background-color:var(--toast-bg);color:#fff;padding:12px 24px;border-radius:24px;font-size:.88rem;font-weight:500;box-shadow:0 4px 15px rgba(0,0,0,.4);z-index:3000;opacity:0;visibility:hidden;transition:opacity .25s,transform .25s,visibility .25s;pointer-events:none;text-align:center;white-space:nowrap}.android-toast.show{transform:translateX(-50%) translateY(0)}@media (max-width:640px){.movie-backdrop-header{height:35vh}.movie-details-layout{margin-top:-80px;padding:0 16px 32px;gap:20px}.movie-header-block{gap:16px}.poster-container{width:100px}.movie-heading{font-size:1.5rem}.movie-summary{font-size:.9rem}.bottom-sheet-modal{border-radius:16px 16px 0 0;padding:20px}.episodes-grid{grid-template-columns:repeat(auto-fill,minmax(60px,1fr));gap:8px}.episode-card{border-radius:6px}.episode-number{font-size:1.2rem}}.footer-copyright{text-align:center;font-size:14px;color:#ffffff21;padding:15px 0}.footer-copyright .author-link{color:inherit;text-decoration:none;font-weight:600}.footer-copyright .author-link:hover,.footer-copyright a{color:#ffffff42;text-decoration:underline}

