b:includable.script:
(function() {
var items = ;
var msgs = ;
var config = ;

// 
var cursor = null;
if (items && items.length > 0) {
cursor = parseInt(items[items.length - 1].timestamp) + 1;
}

var bodyFromEntry = function(entry) {
var text = (entry &&
((entry.content && entry.content.$t) ||
(entry.summary && entry.summary.$t))) ||
'';
if (entry && entry.gd$extendedProperty) {
for (var k in entry.gd$extendedProperty) {
if (entry.gd$extendedProperty[k].name == 'blogger.contentRemoved') {
return '<span class="deleted-comment">' + text + '</span>';
}
}
}
return text;
}

var parse = function(data) {
cursor = null;
var comments = [];
if (data && data.feed && data.feed.entry) {
for (var i = 0, entry; entry = data.feed.entry[i]; i++) {
var comment = {};
// comment ID, parsed out of the original id format
var id = /blog-(\d+).post-(\d+)/.exec(entry.id.$t);
comment.id = id ? id[2] : null;
comment.body = bodyFromEntry(entry);
comment.timestamp = Date.parse(entry.published.$t) + '';
if (entry.author && entry.author.constructor === Array) {
var auth = entry.author[0];
if (auth) {
comment.author = {
name: (auth.name ? auth.name.$t : undefined),
profileUrl: (auth.uri ? auth.uri.$t : undefined),
avatarUrl: (auth.gd$image ? auth.gd$image.src : undefined)
};
}
}
if (entry.link) {
if (entry.link[2]) {
comment.link = comment.permalink = entry.link[2].href;
}
if (entry.link[3]) {
var pid = /.*comments\/default\/(\d+)\?.*/.exec(entry.link[3].href);
if (pid && pid[1]) {
comment.parentId = pid[1];
}
}
}
comment.deleteclass = 'item-control blog-admin';
if (entry.gd$extendedProperty) {
for (var k in entry.gd$extendedProperty) {
if (entry.gd$extendedProperty[k].name == 'blogger.itemClass') {
comment.deleteclass += ' ' + entry.gd$extendedProperty[k].value;
} else if (entry.gd$extendedProperty[k].name == 'blogger.displayTime') {
comment.displayTime = entry.gd$extendedProperty[k].value;
}
}
}
comments.push(comment);
}
}
return comments;
};

var paginator = function(callback) {
if (hasMore()) {
var url = config.feed + '?alt=json&v=2&orderby=published&reverse=false&max-results=50';
if (cursor) {
url += '&published-min=' + new Date(cursor).toISOString();
}
window.bloggercomments = function(data) {
var parsed = parse(data);
cursor = parsed.length < 50 ? null
    : parseInt(parsed[parsed.length - 1].timestamp) + 1
    callback(parsed);
    window.bloggercomments = null;
    }
    url += '&callback=bloggercomments';
    var script = document.createElement('script');
    script.type = 'text/javascript';
    script.src = url;
    document.getElementsByTagName('head')[0].appendChild(script);
    }
    };
    var hasMore = function() {
    return !!cursor;
    };
    var getMeta = function(key, comment) {
    if ('iswriter' == key) {
    var matches = !!comment.author
    && comment.author.name == config.authorName
    && comment.author.profileUrl == config.authorUrl;
    return matches ? 'true' : '';
    } else if ('deletelink' == key) {
    return config.baseUri + '/comment/delete/'
    + config.blogId + '/' + comment.id;
    } else if ('deleteclass' == key) {
    return comment.deleteclass;
    }
    return '';
    };

    var replybox = null;
    var replyUrlParts = null;
    var replyParent = undefined;

    var onReply = function(commentId, domId) {
    if (replybox == null) {
    // lazily cache replybox, and adjust to suit this style:
    replybox = document.getElementById('comment-editor');
    if (replybox != null) {
    replybox.height = '250px';
    replybox.style.display = 'block';
    replyUrlParts = replybox.src.split('#');
    }
    }
    if (replybox && (commentId !== replyParent)) {
    replybox.src = '';
    document.getElementById(domId).insertBefore(replybox, null);
    replybox.src = replyUrlParts[0]
    + (commentId ? '&parentID=' + commentId : '')
    + '#' + replyUrlParts[1];
    replyParent = commentId;
    }
    };

    var hash = (window.location.hash || '#').substring(1);
    var startThread, targetComment;
    if (/^comment-form_/.test(hash)) {
    startThread = hash.substring('comment-form_'.length);
    } else if (/^c[0-9]+$/.test(hash)) {
    targetComment = hash.substring(1);
    }

    // Configure commenting API:
    var configJso = {
    'maxDepth': config.maxThreadDepth
    };
    var provider = {
    'id': config.postId,
    'data': items,
    'loadNext': paginator,
    'hasMore': hasMore,
    'getMeta': getMeta,
    'onReply': onReply,
    'rendered': true,
    'initComment': targetComment,
    'initReplyThread': startThread,
    'config': configJso,
    'messages': msgs
    };

    var render = function() {
    if (window.goog && window.goog.comments) {
    var holder = document.getElementById('comment-holder');
    window.goog.comments.render(holder, provider);
    }
    };

    // render now, or queue to render when library loads:
    if (window.goog && window.goog.comments) {
    render();
    } else {
    window.goog = window.goog || {};
    window.goog.comments = window.goog.comments || {};
    window.goog.comments.loadQueue = window.goog.comments.loadQueue || [];
    window.goog.comments.loadQueue.push(render);
    }
    })();
    //

body.script:
//
document.addEventListener("DOMContentLoaded", () => {
// Interactividad de elementos de UI
const btnPlay = document.getElementById("btn-play");
const toast = document.getElementById("toast");
const modalOverlay = document.getElementById("modal-overlay");
const closeModal = document.getElementById("close-modal");
const serversList = document.getElementById("servers-list");

const videoPlayerOverlay = document.getElementById("video-player-overlay");
const closeVideoPlayer = document.getElementById("close-video-player");
const videoIframe = document.getElementById("video-iframe");

// Función para mostrar Toast Estilo Android
function showToast(message) {
if (!toast) return;
toast.innerText = message;
toast.classList.add("show");
setTimeout(() => {
toast.classList.remove("show");
}, 2000);
}

// Funciones de render de servidores
function renderServers() {
if (!serversList) return;
serversList.innerHTML = "";

if (typeof videoServers === 'undefined' || videoServers.length === 0) {
serversList.innerHTML = `<p style="text-align: center; color: var(--text-secondary); font-size: 0.9rem; padding: 20px 0;">No hay servidores disponibles.</p>`;
return;
}

videoServers.forEach((item, index) => {
const itemDiv = document.createElement("div");
itemDiv.className = "server-item";

// Elegimos un color de fondo sutil según el tipo de servidor
let bgColor = "rgba(255, 255, 255, 0.08)";
let textColor = "#ffffff";

if (item.type.toLowerCase().includes("premium") || item.type.toLowerCase().includes("vip")) {
bgColor = "rgba(52, 168, 83, 0.15)";
textColor = "#34a853";
} else if (item.type.toLowerCase().includes("sin")) {
bgColor = "rgba(25, 118, 210, 0.15)";
textColor = "#4fc3f7";
} else if (item.type.toLowerCase().includes("con anuncios")) {
bgColor = "rgba(245, 124, 0, 0.15)";
textColor = "#ffb74d";
}

itemDiv.innerHTML = `
<div class="server-meta">
    <span class="server-name">${item.server}</span>
    <span class="server-lang">${item.language}</span>
</div>
<button class="server-play-btn" onclick="startVideoPlayer(${index})" style="background-color: ${bgColor}; color: ${textColor}; padding: 8px 14px;">
    ${item.type}
</button>
`;
serversList.appendChild(itemDiv);
});
}

// Al hacer click en "Reproducir"
if (btnPlay) {
btnPlay.addEventListener("click", () => {
showToast("Cargando servidores...");
setTimeout(() => {
renderServers();
if (modalOverlay) modalOverlay.classList.add("active");
}, 800);
});
}

// Cerrar el Modal
if (closeModal && modalOverlay) {
closeModal.addEventListener("click", () => {
modalOverlay.classList.remove("active");
});
}

if (modalOverlay) {
modalOverlay.addEventListener("click", (e) => {
if (e.target === modalOverlay) {
modalOverlay.classList.remove("active");
}
});
}

// Iniciar el reproductor de video
window.startVideoPlayer = function(index) {
if (typeof videoServers === 'undefined' || !videoServers[index]) return;
const selectedServer = videoServers[index];

if (videoIframe) videoIframe.src = selectedServer.url;
const playingTitle = document.getElementById("video-playing-title");
if (playingTitle) {
playingTitle.innerText = `Reproduciendo: (${selectedServer.server} - ${selectedServer.language})`;
}

if (modalOverlay) modalOverlay.classList.remove("active");
if (videoPlayerOverlay) videoPlayerOverlay.classList.add("active");

showToast(`Iniciando reproducción en ${selectedServer.server}`);
}

// Cerrar el reproductor de video
if (closeVideoPlayer) {
closeVideoPlayer.addEventListener("click", () => {
if (videoPlayerOverlay) videoPlayerOverlay.classList.remove("active");
if (videoIframe) videoIframe.src = ""; // Parar el video
});
}
});
//

//
document.addEventListener("DOMContentLoaded", () => {
// Elementos de la UI de series
const episodesContainer = document.getElementById("episodes-container");

const toast = document.getElementById("toast");
const modalOverlay = document.getElementById("modal-overlay");
const closeModal = document.getElementById("close-modal");
const serversList = document.getElementById("servers-list");
const modalServersHeading = document.getElementById("modal-servers-heading");

const videoPlayerOverlay = document.getElementById("video-player-overlay");
const closeVideoPlayer = document.getElementById("close-video-player");
const videoIframe = document.getElementById("video-iframe");
const videoPlayingTitle = document.getElementById("video-playing-title");

// Si no estamos en una pantalla con episodios, detenemos la ejecución de este script
if (!episodesContainer) return;

let selectedSeason = "1";
let selectedEpisode = 1;

// Función para mostrar Toast Estilo Android
function showToast(message) {
if (!toast) return;
toast.innerText = message;
toast.classList.add("show");
setTimeout(() => {
toast.classList.remove("show");
}, 2000);
}

// Renderizar la grilla de episodios según la temporada seleccionada
function renderEpisodes() {
if (!episodesContainer) return;
episodesContainer.innerHTML = "";

if (typeof seriesMeta === 'undefined' || !seriesMeta.seasons) {
episodesContainer.innerHTML = `<p style="text-align: center; color: var(--text-secondary); padding: 20px 0; grid-column: 1 / -1;">No hay información disponible para la serie.</p>`;
return;
}
const episodesList = seriesMeta.seasons[selectedSeason] || [];

if (episodesList.length === 0) {
episodesContainer.innerHTML = `<p style="text-align: center; color: var(--text-secondary); padding: 20px 0; grid-column: 1 / -1;">No hay episodios disponibles para esta temporada.</p>`;
return;
}

episodesList.forEach((ep) => {
const i = ep.episode;
const card = document.createElement("div");
card.className = "episode-card";
card.setAttribute("role", "button");
card.setAttribute("aria-label", `Episodio ${i}`);
card.innerHTML = `
<span class="episode-number">${i}</span>
<span class="episode-tag">Ep</span>
`;

// Al hacer click, guardamos el estado y abrimos el selector de servidores
card.addEventListener("click", () => {
selectedEpisode = i;
triggerServerSelector();
});

episodesContainer.appendChild(card);
});
}

// Obtener los servidores correspondientes al episodio actual de la temporada actual
function getCurrentEpisodeServers() {
if (typeof seriesMeta === 'undefined' || !seriesMeta.seasons) return [];
const episodesList = seriesMeta.seasons[selectedSeason] || [];
const epData = episodesList.find(e => e.episode === selectedEpisode);
return epData ? epData.servers : [];
}

// Iniciar flujo de servidores al clicar en un episodio
function triggerServerSelector() {
showToast(`Cargando servidores para Ep.${selectedEpisode}...`);

setTimeout(() => {
// Actualizar título de menú de opciones
if (modalServersHeading) {
modalServersHeading.innerText = `Servidores: T${selectedSeason} - E${selectedEpisode}`;
}

// Renderizar servidores disponibles
renderServers();

// Mostrar modal bottom sheet
if (modalOverlay) modalOverlay.classList.add("active");
}, 800);
}

// Renderizar los servidores de video en el bottom sheet
function renderServers() {
if (!serversList) return;
serversList.innerHTML = "";
const currentServers = getCurrentEpisodeServers();

if (currentServers.length === 0) {
serversList.innerHTML = `<p style="text-align: center; color: var(--text-secondary); font-size: 0.9rem; padding: 20px 0;">No hay servidores disponibles para este capítulo.</p>`;
return;
}

currentServers.forEach((item, index) => {
const itemDiv = document.createElement("div");
itemDiv.className = "server-item";

// Determinar colores según el tipo de servidor
let bgColor = "rgba(255, 255, 255, 0.08)";
let textColor = "#ffffff";

if (item.type.toLowerCase().includes("premium") || item.type.toLowerCase().includes("vip")) {
bgColor = "rgba(52, 168, 83, 0.15)";
textColor = "#34a853";
} else if (item.type.toLowerCase().includes("sin")) {
bgColor = "rgba(25, 118, 210, 0.15)";
textColor = "#4fc3f7";
} else if (item.type.toLowerCase().includes("con anuncios")) {
bgColor = "rgba(245, 124, 0, 0.15)";
textColor = "#ffb74d";
}

itemDiv.innerHTML = `
<div class="server-meta">
    <span class="server-name">${item.server}</span>
    <span class="server-lang">${item.language}</span>
</div>
<button class="server-play-btn" onclick="startVideoPlayer(${index})" style="background-color: ${bgColor}; color: ${textColor}; padding: 8px 14px;">
    ${item.type}
</button>
`;
serversList.appendChild(itemDiv);
});
}

// Cerrar el Modal
if (closeModal && modalOverlay) {
closeModal.addEventListener("click", () => {
modalOverlay.classList.remove("active");
});
}

if (modalOverlay) {
modalOverlay.addEventListener("click", (e) => {
if (e.target === modalOverlay) {
modalOverlay.classList.remove("active");
}
});
}

// Iniciar la reproducción del capitulo en pantalla completa
window.startVideoPlayer = function(index) {
const currentServers = getCurrentEpisodeServers();
const selectedServer = currentServers[index];

if (!selectedServer) return;

// Apuntar el iframe a la URL del video y configurar título
if (videoIframe) videoIframe.src = selectedServer.url;
if (videoPlayingTitle) {
const seriesTitle = (typeof seriesMeta !== 'undefined' && seriesMeta.title) ? seriesMeta.title : "Serie";
videoPlayingTitle.innerText = `Reproduciendo: ${seriesTitle} • T${selectedSeason}xE${selectedEpisode} (${selectedServer.server} - ${selectedServer.language})`;
}

// Cerrar modal
if (modalOverlay) modalOverlay.classList.remove("active");

// Mostrar overlay del reproductor táctil completo
if (videoPlayerOverlay) videoPlayerOverlay.classList.add("active");

showToast(`Reproduciendo Episodio ${selectedEpisode} en ${selectedServer.server}`);
};

// Cerrar el reproductor de video
if (closeVideoPlayer) {
closeVideoPlayer.addEventListener("click", () => {
if (videoPlayerOverlay) videoPlayerOverlay.classList.remove("active");
if (videoIframe) videoIframe.src = ""; // Parar la reproducción
});
}

// Función para terminar de vincular y pintar la serie
function initSeries() {
const seasonTabs = document.querySelectorAll(".season-tab");
// Al cambiar la temporada, renderizar de nuevo la grilla de episodios
if (seasonTabs && seasonTabs.length > 0) {
seasonTabs.forEach(tab => {
tab.addEventListener("click", () => {
seasonTabs.forEach(t => t.classList.remove("active"));
tab.classList.add("active");
selectedSeason = tab.getAttribute("data-season");
renderEpisodes();
});
});
}
renderEpisodes();
}

// Esperar dinámicamente a que la variable global seriesMeta esté definida
if (typeof seriesMeta === "undefined") {
let attempts = 0;
const checkInterval = setInterval(() => {
attempts++;
if (typeof seriesMeta !== "undefined") {
clearInterval(checkInterval);
initSeries();
} else if (attempts > 60) { // 3 segundos máximo (60 * 50ms)
clearInterval(checkInterval);
episodesContainer.innerHTML = `<p style="text-align: center; color: var(--text-secondary); padding: 20px 0; grid-column: 1 / -1;">Error: No se encontró la configuración de la serie (seriesMeta).</p>`;
}
}, 50);
} else {
initSeries();
}
});
//
